kim anyat kāma-haitukam\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4176,\"bb\":3673,\"url_path\":\"/en/library/bg/16/8/b3673/\",\"shadow_value\":\"asatyam – unreal; apratiṣṭham – without foundation; te – they; jagat – the cosmic manifestation; āhuḥ – say; anīśvaram – with no controller; aparaspara – without cause; sambhūtam – arisen; kim anyat – there is no other cause; kāma-haitukam – it is due to lust only.\",\"word_for_word_value\":[{\"word\":\"asatyam\",\"translation\":\"unreal\"},{\"word\":\"apratiṣṭham\",\"translation\":\"without foundation\"},{\"word\":\"te\",\"translation\":\"they\"},{\"word\":\"jagat\",\"translation\":\"the cosmic manifestation\"},{\"word\":\"āhuḥ\",\"translation\":\"say\"},{\"word\":\"anīśvaram\",\"translation\":\"with no controller\"},{\"word\":\"aparaspara\",\"translation\":\"without cause\"},{\"word\":\"sambhūtam\",\"translation\":\"arisen\"},{\"word\":\"kim anyat\",\"translation\":\"there is no other cause\"},{\"word\":\"kāma-haitukam\",\"translation\":\"it is due to lust only\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4177,\"bb\":3674,\"url_path\":\"/en/library/bg/16/8/b3674/\",\"body_value\":\"They say that this world is unreal, with no foundation, no God in control. They say it is produced of sex desire and has no cause other than lust.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4178,\"bb\":3675,\"url_path\":\"/en/library/bg/16/8/b3675/\",\"body_value\":\"$25\"}]}],\"short_title\":\"Bg. 16.8\",\"medium_title\":\"Bhagavad-gītā As It Is 16.8\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_n